const webhook = $('Webhook').first();
const norm = $('Normalize Order').first().json;
const b = norm.body;
if (!b || typeof b !== 'object' || Object.keys(b).length === 0) {
  throw new Error('Order payload is empty - send application/json, or multipart/form-data with an `order` part');
}
const is_multipart = norm.is_multipart === true;

// ---- optional artwork -------------------------------------------------------
// Contract: artwork is OPTIONAL. If a caller wants to submit artwork it MUST be
// the multipart file field named `artWork`, and must be a jpg or png. Any other
// file field is ignored on purpose; a non-image `artWork` is ignored as well.
// The bytes are read from the Webhook node (the binary does not survive
// Process Order, so it is addressed by node reference rather than carried).
const artBinary = webhook.binary?.artWork;
let art_work_provided = false;
let art_work_extension = null;
let art_work_file_name = null;
let art_work_mime_type = null;
let art_work_invalid = false;
if (artBinary) {
  const mime = String(artBinary.mimeType ?? '').toLowerCase();
  const name = String(artBinary.fileName ?? '');
  const ext = (name.match(/\.([a-z0-9]+)$/i)?.[1] ?? '').toLowerCase();
  const isPng = mime === 'image/png' || ext === 'png';
  const isJpg = mime === 'image/jpeg' || mime === 'image/jpg' || ext === 'jpg' || ext === 'jpeg';
  if (isPng || isJpg) {
    art_work_provided = true;
    art_work_extension = isPng ? 'png' : 'jpg';
    art_work_file_name = name || null;
    art_work_mime_type = mime || null;
  } else {
    art_work_invalid = true;   // artWork supplied but not jpg/png -> ignored
  }
}

const now = new Date();
const order_id = `TS-${now.toISOString().slice(0, 10).replace(/-/g, '')}-` +
                 Math.random().toString(36).slice(2, 8).toUpperCase();

const cfg = Object.fromEntries(
  $('Load Config').all().map(r => [r.json.name, r.json.value])
);
const customer_ref = String(b.customerReferenceNumber ?? '').trim();
if (!customer_ref || customer_ref.length > 64) {
  // return validation error → 422 "customerReferenceNumber is required (max 64 chars)"
}
const idem_key = `${b.customerId}|${customer_ref}`;
// No row means the caller sent an unknown/inactive customerId; fall back to {}
// so the check below reports it instead of throwing on a missing item.
const cust = $('Lookup Customer').all().map(i => i.json)[0] ?? {};
if (!cust.customer_id || !cust.is_active) {
  throw new Error('Customer not found or inactive');
}
return [{
  json: {
    ...b,                          // original order: customerId, orderType, lineItems, billing, shipping
    order_id,
    reference_url: b.referenceNumber,
    customer_reference_number: customer_ref,
    idem_key,
    created_at: now.toISOString(),
    vtiger_base_url: cfg.vtiger_base_url,
    vtiger_assigned_user_id: cust.vtiger_assigned_user_id || cfg.vtiger_assigned_user_id,
    customer_id: cust.customer_id,  
    vtiger_account_id: cust.vtiger_account_id,
    stripe_customer_id: cust.stripe_customer_id,
    // artwork / transport metadata
    is_multipart,
    art_work_provided,
    art_work_field: art_work_provided ? 'artWork' : null,
    art_work_file_name,
    art_work_mime_type,
    art_work_extension,
    art_work_invalid
  }
}];

// ---- Pilot constants (move to customer config later) ----
//const ADDRESS = { bill_street: 'TBD', ship_street: 'TBD' }; // confirm via /describe

const ctx    = $('Build Context').first().json;
const priced = $('Process Order').first().json;
const lookup = $('Validate Product Lookup').first().json;

//shipping and billing address come from the input JSON order
// ---- Billing / shipping from the order payload ----
const clean = v => (v ?? '').toString().trim();
const fullName = a => [clean(a.firstName), clean(a.lastName)].filter(Boolean).join(' ');

const bill = ctx.billing ?? {};
const ship = ctx.shipping ?? {};

const REQUIRED = ['firstName', 'lastName', 'address1', 'city', 'state', 'postcode'];
const missing = [
  ...REQUIRED.filter(k => !clean(bill[k])).map(k => `billing.${k}`),
  ...REQUIRED.filter(k => !clean(ship[k])).map(k => `shipping.${k}`)
];
if (missing.length) throw new Error(`Missing address fields: ${missing.join(', ')}`);

// Field names follow the Zapier implementation; confirm against /describe?elementType=SalesOrder
const ADDRESS = {
  cf_salesorder_billtonamenew:    fullName(bill),
  cf_salesorder_billtocompanynew: clean(bill.company),
  cf_1497:                        clean(bill.phone),        // bill-to phone
  bill_street:                    clean(bill.address1),
  bill_pobox:                     clean(bill.address2),     // Zapier puts address line 2 here
  bill_city:                      clean(bill.city),
  bill_state:                     clean(bill.state),
  bill_code:                      clean(bill.postcode),
  bill_country:                   clean(bill.country) || 'US',

  cf_salesorder_shiptonamenew:    fullName(ship),
  cf_salesorder_shiptocompanynew: clean(ship.company),
  cf_1499:                        clean(ship.phone),        // ship-to phone
  ship_street:                    clean(ship.address1),
  ship_pobox:                     clean(ship.address2),
  ship_city:                      clean(ship.city),
  ship_state:                     clean(ship.state),
  ship_code:                      clean(ship.postcode),
  ship_country:                   clean(ship.country) || 'US'
};

// CRM identity comes from configuration, not from constants in this node:
// the account from the customer's api_customers row, the owner from env_config.
if (!ctx.vtiger_account_id) {
  throw new Error(`Customer ${ctx.customer_id} has no vtiger_account_id configured`);
}
if (!ctx.vtiger_assigned_user_id) {
  throw new Error('env_config.vtiger_assigned_user_id is not set');
}

// Product Number -> VTiger Products record id, asserted complete upstream.
const idByProductNumber = lookup.by_product_number ?? {};

// Invariant: every line item must carry a CRM product id. This is only
// reachable if the lookup validation is bypassed, so fail loudly rather than
// create a sales order whose lines reference no product.
const unresolved = priced.line_items
  .filter(l => !idByProductNumber[String(l.product_number).trim()])
  .map(l => `${l.sku} (Product Number ${l.product_number})`);
if (unresolved.length) {
  throw new Error(`No VTiger product id resolved for: ${unresolved.join('; ')}`);
}

const element = {
  //subject: `Order ${ctx.order_id}${ctx.po_number ? ' / PO ' + ctx.po_number : ''}`,
  subject: `Order ${ctx.order_id} / PO ${ctx.customer_reference_number}`,
  account_id: ctx.vtiger_account_id,
  assigned_user_id: ctx.vtiger_assigned_user_id,
  sostatus: 'Created',
  //purchaseorder: ctx.po_number ?? '',
  vtiger_purchaseorder: ctx.customer_reference_number,
  customerno: ctx.order_id,          // your order id as external reference
  ...ADDRESS,
  hdnTaxType: 'group',
  LineItems: priced.line_items.map(l => ({
    productid: idByProductNumber[String(l.product_number).trim()],
    quantity: l.quantity,
    listprice: (l.unit_amount_cents / 100).toFixed(2)
  }))
};

// Serialisation to a JSON string happens in Create SalesOrder, at the point
// it is needed: VTiger wants `element` as a string in a form-urlencoded body.
// Keeping it an object here means the node's output stays readable.
return [{ json: { element } }];

const order = $('Build Context').first().json;

// Students live on the line items (lineItems[].personalizationData[]).
// Orders may legitimately carry no students at all.
const students = (order.lineItems ?? []).flatMap(li =>
  (li.personalizationData ?? []).map(s => ({
    studentId: s.studentId ?? '',
    firstName: s.firstName ?? '',
    lastName:  s.lastName  ?? ''
  }))
).filter(s => s.studentId || s.firstName || s.lastName);

const has_students = students.length > 0;
const flags = {
  has_students,
  art_work_provided: order.art_work_provided === true
};

const rows = students.map(s => ({ json: { ...s, ...flags } }));

// A zero-item result stops this branch (Students CSV -> Build Uploads -> ...
// -> Respond Created would be skipped) and the caller would get no 201 for an
// order that has already been created and charged. Always emit at least one
// item so the response path always runs; the sentinel is not treated as a
// student by Build Uploads (has_students is false).
return rows.length
  ? rows
  : [{ json: { studentId: '', firstName: '', lastName: '', ...flags } }];

const ctx = $('Build Context').first().json;
const priced = $('Process Order').first().json;
const fmt = c => (c / 100).toFixed(2);

const studentItems = $('Students').all();
const hasStudents = studentItems[0]?.json?.has_students === true;

return [{ json: {
  order_id: ctx.order_id,
  order_number: $('Build Uploads').first().json.order_number,
  //po_number: ctx.po_number,
  customerReferenceNumber: ctx.customer_reference_number,
  customer_id: ctx.customer_id,
  status: 'in process',
  created_at: ctx.created_at,
  currency: priced.currency,
  line_items: priced.line_items.map(l => ({
    sku: l.sku,
    title: l.title,
    quantity: l.quantity,
    unit_price: fmt(l.unit_amount_cents),
    line_total: fmt(l.line_total_cents),
    lead_time: l.lead_time,
    //crm_sales_order_id: so.id,
    //crm_sales_order_no: so.salesorder_no
  })),
  student_count: hasStudents ? studentItems.length : 0,
  art_work_provided: ctx.art_work_provided === true,
  total_amount: fmt(priced.total_cents)
} }];

// Validate the VTiger Products query before anything is built from it.
//
// VTiger's query API is quietly tolerant in three separate ways, none of which
// is an error at the transport level:
//   * an unmatched lookup answers HTTP 200 with {"success": true, "result": []}
//   * a column that does not exist comes back as "" instead of failing
//   * responses are served as text/html, so the HTTP node may hand back the raw
//     text under `data` rather than a parsed object under `body`
// Every one of those would silently produce a sales order with no product on
// its lines, so nothing downstream may proceed on an unverified lookup.
const raw = $input.first().json;
const wanted = [...new Set(
  $('Process Order').first().json.line_items.map(l => String(l.product_number).trim())
)];

const fail = (reason) => [{ json: { ok: false, lookup_error: reason } }];

// Lookup Products requests responseFormat=json; fall back to parsing raw `data`
// so that a node copied from elsewhere still fails loudly instead of silently.
let payload = raw.body !== undefined ? raw.body : raw.data;
if (typeof payload === 'string') {
  try {
    payload = payload.trim() === '' ? null : JSON.parse(payload);
  } catch {
    payload = null;
  }
}

if (raw.statusCode !== undefined && raw.statusCode !== 200) {
  return fail(`VTiger Products query failed with HTTP ${raw.statusCode}${raw.statusMessage ? ' ' + raw.statusMessage : ''}`);
}
if (payload === null || typeof payload !== 'object') {
  return fail('VTiger Products query returned a response that is not JSON');
}
if (payload.success !== true) {
  return fail(`VTiger Products query was rejected: ${JSON.stringify(payload.error ?? payload)}`);
}
if (!Array.isArray(payload.result)) {
  return fail('VTiger Products query returned no result array');
}
if (payload.result.length === 0) {
  return fail(`VTiger has no Products matching: ${wanted.join(', ')}`);
}
if (payload.result.some(r => r.productname === undefined || r.productname === null)) {
  return fail('VTiger response is missing the productname column');
}

const byProductNumber = {};
for (const r of payload.result) {
  const name = String(r.productname).trim();
  if (name && r.id) byProductNumber[name] = r.id;
}

const missing = wanted.filter(n => !byProductNumber[n]);
if (missing.length) {
  return fail(`Product Number(s) not found in VTiger Products: ${missing.join(', ')}`);
}

return [{ json: { ok: true, by_product_number: byProductNumber, matched_count: payload.result.length } }];

const ctx = $('Build Context').first().json;

// The VTiger order number returned on creation, e.g. "1234" -> "1234.png"/"1234.csv".
// If the CRM step was skipped (dry run with no CRM/Stripe), fall back to the
// internal order id so the upload path stays testable.
let so = {};
try {
  so = $('Create SalesOrder').first().json.body?.result ?? {};
} catch (e) { /* Create SalesOrder did not run */ }
const orderNo = so.salesorder_no ?? so.id ?? ctx.order_id;

const hasStudents = $('Students').first().json.has_students === true;
const hasArtwork  = ctx.art_work_provided === true;

const items = [];

// Students CSV -> "<vtiger order number>.csv"
if (hasStudents) {
  const csv = $input.first()?.binary?.data;
  if (csv) {
    items.push({ json: { upload_file_name: `${orderNo}.csv` }, binary: { data: csv } });
  }
}

// artWork -> "<vtiger order number>.<ext>"  (reads the original upload; the
// binary does not survive Process Order, so it is taken from the Webhook node)
if (hasArtwork) {
  const art = $('Webhook').first().binary?.artWork;
  if (art) {
    items.push({ json: { upload_file_name: `${orderNo}.${ctx.art_work_extension}` }, binary: { data: art } });
  }
}

// Nothing to upload -> emit a single marker so the branch continues to the
// confirmation instead of dead-ending.
if (!items.length) {
  return [{ json: { has_upload: false, order_number: orderNo } }];
}
return items.map(i => ({ json: { ...i.json, has_upload: true, order_number: orderNo }, binary: i.binary }));

const webhook = $('Webhook').first();
const headers = webhook.json.headers ?? {};
const is_multipart = String(headers['content-type'] ?? '').toLowerCase().startsWith('multipart/form-data');

// multipart/form-data parts are flat, so the nested order payload rides in a
// single part named `order` - as a TEXT field (paste the JSON) or as an
// uploaded .json FILE (read by the `Read Order File` node). It is merged over
// any flat form fields so the rest of the workflow sees the same canonical
// `body` shape it would get from an application/json request.
let body = (webhook.json.body && typeof webhook.json.body === 'object') ? webhook.json.body : {};

if (is_multipart) {
  let raw = null;
  if (typeof body.order === 'string') {
    raw = body.order;                                   // `order` sent as a text field
  } else {
    try {
      const read = $('Read Order File').first().json;   // set only when a file was read
      if (typeof read?.data === 'string') raw = read.data;
    } catch (e) { /* Read Order File did not run: there was no order file */ }
  }
  if (raw !== null) {
    let parsed;
    try {
      parsed = JSON.parse(raw);
    } catch (e) {
      throw new Error(`multipart part 'order' is not valid JSON: ${e.message}`);
    }
    const { order, ...rest } = body;   // drop the raw part; do not carry it downstream
    body = { ...rest, ...parsed };
  }
}

return [{ json: { ...webhook.json, body, is_multipart } }];
